```tsx
// Page «Главная» (/) of the public site, written by the page composer v3 (V3-12).
// Sections: header-split-nav, hero-centered, services-editorial, catalog-list, form-centered, contacts-cards, footer-panels.
import { useEffect } from "react";
import { useSitePhotos } from "@wizard/ui-kit/v3/headless";
import HeaderSplitNav from "../../patterns/header-split-nav";
import HeroCentered from "../../patterns/hero-centered";
import ServicesEditorial from "../../patterns/services-editorial";
import CatalogList from "../../patterns/catalog-list";
import FormCentered from "../../patterns/form-centered";
import ContactsCards from "../../patterns/contacts-cards";
import FooterPanels from "../../patterns/footer-panels";

export default function HomePage() {
  const photo = useSitePhotos();
  useEffect(() => {
    const id = location.hash.slice(1);
    const target = id ? document.getElementById(id) : null;
    if (!target) return;
    target.scrollIntoView();
    const keep = new ResizeObserver(() => target.scrollIntoView());
    keep.observe(document.body);
    const stop = () => keep.disconnect();
    const timer = setTimeout(stop, 3000);
    for (const e of ["wheel", "touchstart", "keydown"]) addEventListener(e, stop, { once: true, passive: true });
    return () => {
      clearTimeout(timer);
      stop();
      for (const e of ["wheel", "touchstart", "keydown"]) removeEventListener(e, stop);
    };
  }, []);
  return (
    <>
      <HeaderSplitNav {...{"brand":{"name":"Белая линия","href":"/"},"nav":[{"label":"Главная","href":"/"},{"label":"Каталог и цены","href":"/services"}],"action":{"label":"Оставить заявку","href":"#form"}}} />
      <main id="main">
        <div id="hero">
          <HeroCentered {...{"title":"Лечим зубы без боли и очередей","lead":"Оставьте заявку — перезвоним за 15 минут","action":{"label":"Оставить заявку","href":"#form"},"secondary":{"label":"Открыть каталог","href":"/services"}}} image={photo.one("top", undefined)} />
        </div>
        <div id="services">
          <ServicesEditorial {...{"title":"Почему мы","items":[{"title":"Современное оборудование"},{"title":"Анестезия","text":"Лечим без боли"}]}} />
        </div>
        <div id="catalog">
          <CatalogList {...{"entity":"service","title":"Услуги и цены","empty":"В каталоге пока нет позиций","action":{"label":"Весь каталог","href":"/services"},"pageSize":6,"preview":true,"itemAction":{"label":"Оставить заявку","path":"/#form"}}} />
        </div>
        <div id="form">
          <FormCentered {...{"entity":"lead","title":"Оставьте заявку","text":"Перезвоним и подберём время","submit":"Отправить заявку","sent":{"title":"Заявка отправлена"},"again":"Отправить ещё одну заявку","contact":{"label":"+7 900 000-00-00","href":"tel:+7 900 000-00-00"}}} />
        </div>
        <div id="contacts">
          <ContactsCards {...{"title":"Контакты","address":{"text":"Казань, ул. Баумана, 15"},"phones":[{"number":"+7 900 000-00-00","href":"tel:+7 900 000-00-00"}]}} />
        </div>
      </main>
      <FooterPanels {...{"brand":{"name":"Белая линия","href":"/"},"legal":{"operator":"© 2026 ООО «Белая линия»","policy":{"label":"Политика обработки персональных данных","href":"/privacy"}},"contacts":[{"label":"Телефон","value":"+7 900 000-00-00","href":"tel:+7 900 000-00-00"},{"label":"Адрес","value":"Казань, ул. Баумана, 15"}],"columns":[{"title":"Разделы","links":[{"label":"Главная","href":"/"},{"label":"Каталог и цены","href":"/services"}]}]}} />
    </>
  );
}

```

